import javax.swing.*;import java.awt.*;import java.awt.image.*;import javax.imageio.*;import java.io.*;
public class LoginPreview {static void layout(Container c){c.doLayout();for(Component x:c.getComponents())if(x instanceof Container)layout((Container)x);}public static void main(String[]args)throws Exception{UIManager.setLookAndFeel("javax.swing.plaf.nimbus.NimbusLookAndFeel");SwingUtilities.invokeAndWait(()->{var f=new QuizoraApp.Ui.Auth.loginForm();try{layout(f.getContentPane());var im=new BufferedImage(f.getContentPane().getWidth(),f.getContentPane().getHeight(),BufferedImage.TYPE_INT_RGB);var g=im.createGraphics();f.getContentPane().printAll(g);g.dispose();ImageIO.write(im,"png",new File("Build/login-preview.png"));System.out.println("Rendered "+im.getWidth()+" x "+im.getHeight());}catch(Exception e){throw new RuntimeException(e);}finally{f.dispose();}});}}
